/// <summary>
/// Base class for PricingAttribute table <c>RetailSalesTable</c>
/// </summary>
internal abstract class GUPPricingAttributeRetailSalesTable extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
    protected RetailSalesTable getTableRecord(Common _pricingObject)
    {
        SalesTable   salesTable = _pricingObject as SalesTable;
        RetailSalesTable retailSalesTable;
        
        if (salesTable)
        {
            retailSalesTable = salesTable.retailSalesTable();
        }

        return retailSalesTable;
    }

    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbdsRoot;

        if (_qbdsMap && _qbdsMap.exists(tableStr(RetailSalesTable)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(RetailSalesTable));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(RetailSalesTable));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(RetailSalesTable), qbdsRoot);
            }
        }

        return qbdsRoot;
    }

    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }
